import { emitParseResult, parseTest18Args } from './lib/cli/argparse_like.mjs';
import { runReferenceExecutable } from './lib/runtime/reference_runner.mjs';
import { basenameFromPath } from './lib/shared/path_utils.mjs';

const programName = basenameFromPath(process.argv[1]);
const parsedValues = emitParseResult(parseTest18Args(process.argv.slice(2), programName));
const result = runReferenceExecutable(parsedValues);

if (result.error) {
  throw result.error;
}

if (result.stdout.length > 0) {
  process.stdout.write(result.stdout);
}

if (result.stderr.length > 0) {
  process.stderr.write(result.stderr);
}

process.exit(result.code);

import {
  HELP_FLAGS,
  OPTION_ARGUMENT_LABELS,
  OPTION_FLAGS,
  OPTION_NAMES,
} from '../shared/options.mjs';

const MAX_USAGE_WIDTH = 78;

function buildUsageSegments() {
  return ['[-h]', ...OPTION_NAMES.map((name) => `--${name} ${OPTION_ARGUMENT_LABELS[name]}`)];
}

function isNegativeNumberLike(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

function isOptionLikeValue(token) {
  return token !== '-' && token.startsWith('-') && !isNegativeNumberLike(token);
}

function buildUsage(programName) {
  const prefix = `usage: ${programName} `;
  const continuationPrefix = ' '.repeat(prefix.length);
  const lines = [];
  let currentLine = prefix;
  let hasSegmentOnLine = false;

  for (const segment of buildUsageSegments()) {
    const candidate = hasSegmentOnLine ? `${currentLine} ${segment}` : `${currentLine}${segment}`;
    if (hasSegmentOnLine && candidate.length > MAX_USAGE_WIDTH - 1) {
      lines.push(currentLine);
      currentLine = `${continuationPrefix}${segment}`;
      hasSegmentOnLine = true;
      continue;
    }

    currentLine = candidate;
    hasSegmentOnLine = true;
  }

  lines.push(currentLine);
  return `${lines.join('\n')}\n`;
}

function buildOptionsSection() {
  const lines = ['options:', '  -h, --help  show this help message and exit'];
  for (const name of OPTION_NAMES) {
    lines.push(`  --${name} ${OPTION_ARGUMENT_LABELS[name]}`);
  }
  return `${lines.join('\n')}\n`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}${programName}: error: ${message}\n`;
}

function createError(programName, message) {
  return {
    code: 2,
    status: 'error',
    text: buildError(programName, message),
  };
}

function createHelp(programName) {
  return {
    code: 0,
    status: 'help',
    text: `${buildUsage(programName)}\n${buildOptionsSection()}`,
  };
}

function createSuccess(values) {
  return {
    code: 0,
    status: 'ok',
    values,
  };
}

export function formatHelp(programName = 'test18.mjs') {
  return createHelp(programName).text;
}

export function parseTest18Args(argv, programName = 'test18.mjs') {
  const values = {};
  const extras = [];
  const optionFlagSet = new Set(OPTION_FLAGS);

  for (let index = 0; index < argv.length; index += 1) {
    const token = String(argv[index]);

    if (token.startsWith('-h=')) {
      return createError(programName, `argument -h/--help: ignored explicit argument '${token.slice(3)}'`);
    }

    if (token.startsWith('--help=')) {
      return createError(programName, `argument -h/--help: ignored explicit argument '${token.slice(7)}'`);
    }

    if (HELP_FLAGS.includes(token) || (token.startsWith('-h') && !token.startsWith('--'))) {
      return createHelp(programName);
    }

    if (token === '--') {
      extras.push(...argv.slice(index).map(String));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const flag = equalsIndex === -1 ? token : token.slice(0, equalsIndex);

      if (optionFlagSet.has(flag)) {
        const name = flag.slice(2);
        if (equalsIndex !== -1) {
          values[name] = token.slice(equalsIndex + 1);
          continue;
        }

        const nextToken = argv[index + 1];
        if (nextToken === undefined || isOptionLikeValue(String(nextToken))) {
          return createError(programName, `argument ${flag}: expected one argument`);
        }

        values[name] = String(nextToken);
        index += 1;
        continue;
      }

      extras.push(token);
      continue;
    }

    if (isOptionLikeValue(token)) {
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missing = OPTION_NAMES.filter((name) => !(name in values)).map((name) => `--${name}`);
  if (missing.length > 0) {
    return createError(programName, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    return createError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return createSuccess(values);
}

export function emitParseResult(parseResult) {
  if (parseResult.status === 'help') {
    process.stdout.write(parseResult.text);
    process.exit(parseResult.code);
  }

  if (parseResult.status === 'error') {
    process.stderr.write(parseResult.text);
    process.exit(parseResult.code);
  }

  return parseResult.values;
}

export { HELP_FLAGS };

import { spawnSync } from 'node:child_process';

import { OPTION_NAMES, REFERENCE_EXECUTABLE } from '../shared/options.mjs';

export function runReferenceExecutable(values) {
  const args = [];

  for (const name of OPTION_NAMES) {
    args.push(`--${name}`, String(values[name]));
  }

  const result = spawnSync(REFERENCE_EXECUTABLE, args, {
    stdio: 'pipe',
  });

  return {
    code: typeof result.status === 'number' ? result.status : 1,
    error: result.error ?? null,
    stderr: result.stderr ?? Buffer.alloc(0),
    stdout: result.stdout ?? Buffer.alloc(0),
  };
}
